def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # Maps key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries (optional, but good practice)
            # Actually, we need to check on-demand for correctness

            # Check if key already exists and is not expired
            if key in cache:
                _, write_time = cache[key]
                if t < write_time + ttl:
                    # Entry is still valid, update it
                    del cache[key]
                    cache[key] = (value, t)
                else:
                    # Entry is expired, treat as absent
                    cache[key] = (value, t)
            else:
                # Key is absent, check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used (first item in OrderedDict)
                    cache.popitem(last=False)
                cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache:
                value, write_time = cache[key]
                # Check if entry is expired
                if t < write_time + ttl:
                    # Entry is valid, mark as most recently used
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
                else:
                    # Entry is expired
                    del cache[key]
                    results.append(-1)
            else:
                # Key is absent
                results.append(-1)

    return results

